 \label{prop:ls}
The dual block composition satisfies the following properties:
\paragraph{\emph{Preservation of $\ell_1$-norm}:} If $\|\Psi\|_1 = 1$, $\|\psi\|_1 = 1$, and $\langle \psi, \mathbf{1}\rangle = 0$, then
\begin{equation}\|\Psi \star \psi\|_1 = 1. \label{eqn:ls-norm}\end{equation}

\paragraph{\emph{Multiplicativity of pure high degree}:} If $\langle \Psi, P \rangle = 0$ for every polynomial $P \colon \{-1,1\}^M \to \{-1,1\}$ of degree less than  $D$, and $\langle \psi, p \rangle = 0$ for every polynomial $p \colon \{-1,1\}^m \to \{-1,1\}$ of degree less than $d$, then
for every polynomial $q \colon \{-1,1\}^{m \cdot M} \to \{-1,1\}$,
\begin{equation}\deg q < D \cdot d \implies \langle \Psi \star \psi, q \rangle = 0. \label{eqn:ls-phd} \end{equation}

\paragraph{\emph{Associativity}:} For every $\zeta: \{-1,1\}^{m_\zeta} \to \mathbb{R}$, $\varphi: \{-1,1\}^{m_\varphi} \to \mathbb{R}$, and $\psi: \{-1,1\}^{m_\psi} \to \mathbb{R}$, we have
\begin{equation} (\zeta \star \varphi) \star \psi = \zeta \star (\varphi \star \psi). \label{eqn:ls-assoc} \end{equation}

