\begin{equation*} p_{\mathcal{R}} = q\left({\mathds{1}}\left[x_1 = 1\right], {\mathds{1}}\left[x_2=1\right], \dots,
{\mathds{1}}\left[x_N=1\right], {\mathds{1}}\left[x_1=2\right], \dots, {\mathds{1}}\left[x_N=\left|\mathcal{R}\right|\right]\right).
