\end{equation}

\begin{equation} \label{fleck}
    r(x) = \frac{1}{\binom{N}{S}} \sum_{\mathcal{S} \in \binom{[N]}{S}} p_{\mathcal{R}(x_\mathcal{S})}(x). 
\end{equation}

\begin{align}
    r(x) &= \frac{1}{\binom{N}{S}} \sum_{\mathcal{S} \in \binom{[N]}{S}} p_{\mathcal{R}(x_\mathcal{S})}(x) \\
    &= \frac{1}{\binom{N}{S}} \left(\sum_{\mathcal{S} \in \binom{[N]}{S}} \sum_{b=0}^{N/T} {\mathds{1}}[b_{\mathcal{R}(x_\mathcal{S})}(x)=b] \cdot p_{\mathcal{R}(x_\mathcal{S})}(x) \right)\\
    &= \frac{1}{\binom{N}{S}} \sum_{\mathcal{S} \in \binom{[N]}{S}} {\mathds{1}}[b_{\mathcal{R}(x_\mathcal{S})}(x)=0] \cdot p_{\mathcal{R}(x_\mathcal{S})}(x) \label{eq:t1}\\
    &\qquad\qquad\qquad + \sum_{b=1}^{N/T} \frac{1}{\binom{N}{S}} \sum_{\mathcal{S} \in \binom{[N]}{S}}  {\mathds{1}}[b_{\mathcal{R}(x_\mathcal{S})}(x)=b]  \cdot p_{\mathcal{R}(x_\mathcal{S})}(x),
    \label{eq:t2}
