\end{align}

\begin{align*}
E_+(\psi, f) = \{x \in \mathcal{X} : \psi(x) > 0, f(x) = -1\} \\
E_-(\psi, f) = \{x \in \mathcal{X} : \psi(x) < 0, f(x) = +1\}.
\end{align*}

\begin{align} &\sum_{x \in E_+(\psi, f)} |\psi(x)| \le \delta^+ \label{eqn:error-base-pos} \\
& \sum_{x \in E_-(\psi, f)} |\psi(x)| \le \delta^- \label{eqn:error-base-neg} \\
& \|\psi\|_1 = 1.\label{eqn:error-base-norm}
\end{align}

\begin{align} & \sum_{x \in E_+(\varphi \star \psi, \mathsf{ OR}_M \circ f)} |(\varphi \star \psi)(x)| \le M \cdot \delta^+ \label{eqn:error-amp-pos} \\
& \sum_{x \in E_-(\varphi \star \psi, \mathsf{ OR}_M \circ f)} |(\varphi \star \psi)(x)| \le  \frac{1}{2} \cdot (2\delta^-)^M.\label{eqn:error-amp-neg}
\end{align}

\begin{equation}
\langle \rho \star \psi, \mathsf{ OR}_M \circ f \rangle \ge \frac{9}{10} - 4  M \delta^+ - 4\delta^-. \label{eqn:deg-amp-corr}
\end{equation}

