&F^{\le N}(x_1, \dots, x_R) = \begin{cases} f(g(x_1), \dots, g(x_R)) & \text{ if } x_1, \dots, x_R \in \{-1,1\}^N,  |x_1| + \dots + |x_R| \le N,\\
\text{undefined} & \text{otherwise}.
\end{cases}
\end{align*}

